describe('Edit Task Functionality', () => {
  beforeEach(() => {
    cy.visit('/tasks');
  });

  it('should successfully edit an existing task by clicking Edit button', () => {
    // Verify initial task list is displayed
    cy.get('[data-testid="task-list"]').should('be.visible');
    cy.get('[data-testid="task-item"]').should('have.length.greaterThan', 0);

    // Find a task to edit
    cy.get('[data-testid="task-item"]').first().click();

    // Verify edit modal is displayed
    cy.get('[data-testid="edit-modal"]').should('be.visible');

    // Verify form fields are populated with task data
    cy.get('[data-testid="task-name-input"]').should('have.value', 'Initial Task Name');
    cy.get('[data-testid="task-description-input"]').should('have.value', 'Initial Task Description');

    // Verify Save button is visible
    cy.get('[data-testid="save-button"]').should('be.visible');

    // Fill in new task details
    cy.get('[data-testid="task-name-input"]').type('Updated Task Name');
    cy.get('[data-testid="task-description-input"]').type('Updated Task Description');

    // Click Save button
    cy.get('[data-testid="save-button"]').click();

    // Verify success message appears
    cy.get('[data-testid="success-message"]').should('be.visible');
    cy.get('[data-testid="success-message"]').should('contain', 'Task updated successfully');

    // Verify task list is updated
    cy.get('[data-testid="task-item"]').first().should('contain', 'Updated Task Name');

    // Verify edit button is still visible for other tasks
    cy.get('[data-testid="task-item"]').last().should('have.attr', 'data-testid');
  });

  it('should handle empty task name input and display validation error', () => {
    // Find a task to edit
    cy.get('[data-testid="task-item"]').first().click();

    // Verify edit modal is displayed
    cy.get('[data-testid="edit-modal"]').should('be.visible');

    // Fill in task description but leave task name empty
    cy.get('[data-testid="task-description-input"]').type('Updated Task Description');

    // Click Save button
    cy.get('[data-testid="save-button"]').click();

    // Verify validation error message appears
    cy.get('[data-testid="validation-error"]').should('be.visible');
    cy.get('[data-testid="validation-error"]').should('contain', 'Task name cannot be empty');

    // Verify success message does not appear
    cy.get('[data-testid="success-message"]').should('not.exist');

    // Verify task list is not updated
    cy.get('[data-testid="task-item"]').first().should('contain', 'Initial Task Name');

    // Verify edit button is still visible
    cy.get('[data-testid="task-item"]').last().should('have.attr', 'data-testid');
  });
});
